begin
  dut : entity work.control
    port map (opcode => opcode, valid => valid, inject => inject,
              ctrl_raw => ctrl_raw, ctrl => ctrl);

  stim : process
    variable errs : natural := 0;
  begin
    -- 1. plain decode of all 64 opcodes
    valid <= '1'; inject <= '0';
    for i in 0 to 63 loop
      opcode <= std_logic_vector(to_unsigned(i, 6));
      wait for 1 ns;
      check(ctrl_raw = EXP(i), "ctrl_raw opcode=" & integer'image(i), errs);
      check(ctrl = EXP(i), "ctrl opcode=" & integer'image(i), errs);
    end loop;

    -- 2. spot checks of key fields (independent of the table)
    opcode <= OP_CMP; wait for 1 ns;
    check_sl(ctrl.write_port_1_enable, '0', "CMP does not write", errs);
    check_eq(ctrl.alu_operation, ALU_SUB, "CMP uses SUB", errs);
    opcode <= OP_SWAP; wait for 1 ns;
    check_sl(ctrl.write_port_2_enable and ctrl.swap_write_addresses and ctrl.read_port_1_uses_rdst and ctrl.read_port_2_uses_rsrc1, '1', "SWAP", errs);
    opcode <= OP_JN; wait for 1 ns;
    check_eq(ctrl.jump_condition, COND_N, "JN cond", errs);
    check_sl(ctrl.update_zero_negative_flags or ctrl.update_carry_flag, '0', "JN does not touch flags", errs);
    opcode <= OP_STD; wait for 1 ns;
    check_sl(ctrl.base_address_is_operand_b, '1', "STD base is operand B", errs);
    opcode <= OP_SHR; wait for 1 ns;
    check_sl(ctrl.update_carry_flag, '1', "SHR updates C", errs);

    -- 3. valid = '0' -> bubble for every opcode
    valid <= '0';
    for i in 0 to 63 loop
      opcode <= std_logic_vector(to_unsigned(i, 6));
      wait for 1 ns;
      check(ctrl_raw = CTRL_NOP, "bubble raw opcode=" & integer'image(i), errs);
      check(ctrl = CTRL_NOP, "bubble opcode=" & integer'image(i), errs);
    end loop;

    -- 4. inject -> IRQ micro-op, raw decode untouched
    valid <= '1'; inject <= '1';
    for i in 0 to 63 loop
      opcode <= std_logic_vector(to_unsigned(i, 6));
      wait for 1 ns;
      check(ctrl = EXP_HW, "inject opcode=" & integer'image(i), errs);
      check(ctrl_raw = EXP(i), "inject raw opcode=" & integer'image(i), errs);
    end loop;

    finish_tb("tb_control", errs);
    wait;
  end process;
end architecture sim;
